validator:
function validate(input) {
  const [{ Employee = [], Params = [] }] = input;
  if (Params.length !== 1) return 'Params must hold exactly one row.';
  if (Params[0][0] === null || Params[0][0] < 1) return 'N must be at least 1.';
  const ids = new Set();
  for (const [id, salary] of Employee) {
    if (id === null) return 'Every employee needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Employee.`;
    if (salary === null) return `Employee ${id} needs a salary.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const Employee = [];
  if (size === 'small') {
    const salaries = [100, 200, 300, 400, 500];
    const count = pick(9);
    for (let i = 0; i < count; i++) Employee.push([i * 2 + 1, salaries[pick(salaries.length)]]);
    return [{ Employee, Params: [[1 + pick(5)]] }];
  }
  for (let i = 0; i < 2000; i++) Employee.push([i + 1, 1000 + pick(3000)]);
  return [{ Employee, Params: [[1 + pick(1800)]] }];
}
